"use client";

import { useMemo } from "react";
import {
  readApiResource,
  useApiResource,
  type ApiResourceAdapter,
} from "./use-api-resource";

export type PaymentQuoteInput = {
  inputMint: string;
  outputMint: string;
  amount: string;
  slippageBps?: number;
  swapMode?: "ExactIn" | "ExactOut";
};
export type PaymentQuote = {
  inputMint: string;
  outputMint: string;
  inputAmount: string;
  outputAmount: string;
  minimumOutputAmount: string;
  swapMode: "ExactIn" | "ExactOut";
  slippageBps: number;
  priceImpactPct: string;
  routeLabels: string[];
  contextSlot: number | null;
};
export type PaymentQuoteAdapter = ApiResourceAdapter<
  PaymentQuoteInput,
  PaymentQuote
>;

export function createPaymentQuoteAdapter(
  endpoint = "/api/payment-quote",
): PaymentQuoteAdapter {
  return async (input, { signal }) => {
    const url = new URL(endpoint, window.location.origin);
    Object.entries(input).forEach(([key, value]) => {
      if (value !== undefined) url.searchParams.set(key, String(value));
    });
    return readApiResource<PaymentQuote>(await fetch(url, { signal }));
  };
}

export function usePaymentQuote(
  input: PaymentQuoteInput | null,
  options: {
    adapter?: PaymentQuoteAdapter;
    endpoint?: string;
    enabled?: boolean;
  } = {},
) {
  const defaultAdapter = useMemo(
    () => createPaymentQuoteAdapter(options.endpoint),
    [options.endpoint],
  );
  const normalized = input
    ? {
        ...input,
        inputMint: input.inputMint.trim(),
        outputMint: input.outputMint.trim(),
        amount: input.amount.trim(),
        slippageBps: input.slippageBps ?? 50,
        swapMode: input.swapMode ?? ("ExactIn" as const),
      }
    : null;
  const requestKey = normalized ? JSON.stringify(normalized) : "";

  return useApiResource({
    adapter: options.adapter ?? defaultAdapter,
    enabled:
      (options.enabled ?? true) &&
      Boolean(normalized?.inputMint && normalized.outputMint && normalized.amount),
    input:
      normalized ?? {
        inputMint: "",
        outputMint: "",
        amount: "",
        slippageBps: 50,
        swapMode: "ExactIn",
      },
    requestKey,
  });
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

export type ApiResourceStatus = "idle" | "loading" | "success" | "error";

export type ApiResourceError = {
  code: string;
  message: string;
  retryable: boolean;
  status?: number;
};

export type ApiResourceAdapter<Input, Data> = (
  input: Input,
  context: { signal: AbortSignal },
) => Promise<Data>;

export type ApiResourceState<Data> = {
  status: ApiResourceStatus;
  data: Data | null;
  error: ApiResourceError | null;
  updatedAt: string | null;
};

type ApiEnvelope<Data> = {
  data?: Data;
  error?: Partial<ApiResourceError> & { message?: string };
};

export class ApiResourceRequestError extends Error {
  code: string;
  retryable: boolean;
  status?: number;

  constructor(error: ApiResourceError) {
    super(error.message);
    this.name = "ApiResourceRequestError";
    this.code = error.code;
    this.retryable = error.retryable;
    this.status = error.status;
  }
}

export async function readApiResource<Data>(response: Response) {
  let body: ApiEnvelope<Data>;

  try {
    body = (await response.json()) as ApiEnvelope<Data>;
  } catch {
    throw new ApiResourceRequestError({
      code: "INVALID_RESPONSE",
      message: "The provider returned an unreadable response.",
      retryable: true,
      status: response.status,
    });
  }

  if (!response.ok || body.error || body.data === undefined) {
    throw new ApiResourceRequestError({
      code: body.error?.code || "REQUEST_FAILED",
      message: body.error?.message || "The provider request failed.",
      retryable: body.error?.retryable ?? response.status >= 500,
      status: response.status,
    });
  }

  return body.data;
}

function normalizeError(cause: unknown): ApiResourceError {
  if (cause instanceof ApiResourceRequestError) {
    return {
      code: cause.code,
      message: cause.message,
      retryable: cause.retryable,
      status: cause.status,
    };
  }

  return {
    code: "UNKNOWN_ERROR",
    message: cause instanceof Error ? cause.message : "The request failed.",
    retryable: true,
  };
}

export function useApiResource<Input, Data>({
  adapter,
  enabled,
  input,
  requestKey,
}: {
  adapter: ApiResourceAdapter<Input, Data>;
  enabled: boolean;
  input: Input;
  requestKey: string;
}) {
  const inputRef = useRef(input);
  const requestIdRef = useRef(0);
  const [refreshKey, setRefreshKey] = useState(0);
  const [state, setState] = useState<ApiResourceState<Data>>({
    status: "idle",
    data: null,
    error: null,
    updatedAt: null,
  });

  useEffect(() => {
    inputRef.current = input;
  }, [input]);

  useEffect(() => {
    if (!enabled) return;

    const requestId = ++requestIdRef.current;
    const controller = new AbortController();
    const loadingTimer = window.setTimeout(() => {
      setState((current) => ({
        ...current,
        status: "loading",
        error: null,
      }));
    }, 0);

    void adapter(inputRef.current, { signal: controller.signal })
      .then((data) => {
        window.clearTimeout(loadingTimer);
        if (controller.signal.aborted || requestId !== requestIdRef.current) {
          return;
        }
        setState({
          status: "success",
          data,
          error: null,
          updatedAt: new Date().toISOString(),
        });
      })
      .catch((cause: unknown) => {
        window.clearTimeout(loadingTimer);
        if (controller.signal.aborted || requestId !== requestIdRef.current) {
          return;
        }
        setState((current) => ({
          ...current,
          status: "error",
          error: normalizeError(cause),
        }));
      });

    return () => {
      window.clearTimeout(loadingTimer);
      controller.abort();
    };
  }, [adapter, enabled, refreshKey, requestKey]);

  const refetch = useCallback(() => setRefreshKey((value) => value + 1), []);
  const visibleState: ApiResourceState<Data> = enabled
    ? state
    : { status: "idle", data: null, error: null, updatedAt: null };

  return {
    ...visibleState,
    isIdle: visibleState.status === "idle",
    isLoading: visibleState.status === "loading",
    isSuccess: visibleState.status === "success",
    isError: visibleState.status === "error",
    refetch,
  };
}

import { NextResponse } from "next/server";

export const runtime = "nodejs";
const JUPITER_QUOTE_URL = "https://api.jup.ag/swap/v1/quote";
const BASE58_PUBLIC_KEY = /^[1-9A-HJ-NP-Za-km-z]{32,44}$/;

function jsonError(code: string, message: string, status: number, retryable = false) {
  return NextResponse.json({ error: { code, message, retryable } }, { status });
}

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const inputMint = searchParams.get("inputMint")?.trim() ?? "";
  const outputMint = searchParams.get("outputMint")?.trim() ?? "";
  const amount = searchParams.get("amount")?.trim() ?? "";
  const slippageBps = Math.min(5_000, Math.max(0, Number(searchParams.get("slippageBps")) || 50));
  const swapMode = searchParams.get("swapMode") === "ExactOut" ? "ExactOut" : "ExactIn";
  const apiKey = process.env.JUPITER_API_KEY;

  if (!BASE58_PUBLIC_KEY.test(inputMint) || !BASE58_PUBLIC_KEY.test(outputMint)) {
    return jsonError("INVALID_MINT", "Valid input and output token mints are required.", 400);
  }
  if (!/^\d+$/.test(amount) || BigInt(amount) <= 0n) {
    return jsonError("INVALID_AMOUNT", "Amount must be a positive integer in atomic units.", 400);
  }
  if (!apiKey) return jsonError("MISSING_CONFIGURATION", "Missing JUPITER_API_KEY.", 500);

  const url = new URL(JUPITER_QUOTE_URL);
  url.searchParams.set("inputMint", inputMint);
  url.searchParams.set("outputMint", outputMint);
  url.searchParams.set("amount", amount);
  url.searchParams.set("slippageBps", String(slippageBps));
  url.searchParams.set("swapMode", swapMode);

  try {
    const response = await fetch(url, { headers: { "x-api-key": apiKey }, cache: "no-store" });
    const payload = (await response.json()) as Record<string, unknown>;
    if (!response.ok) {
      return jsonError("QUOTE_UNAVAILABLE", "No executable payment quote is available.", 502, true);
    }
    const routePlan = Array.isArray(payload.routePlan) ? payload.routePlan : [];
    const routeLabels = routePlan.flatMap((route) => {
      if (!route || typeof route !== "object") return [];
      const swapInfo = (route as Record<string, unknown>).swapInfo;
      if (!swapInfo || typeof swapInfo !== "object") return [];
      const label = (swapInfo as Record<string, unknown>).label;
      return typeof label === "string" ? [label] : [];
    });
    return NextResponse.json({
      data: {
        inputMint,
        outputMint,
        inputAmount: String(payload.inAmount ?? amount),
        outputAmount: String(payload.outAmount ?? "0"),
        minimumOutputAmount: String(payload.otherAmountThreshold ?? "0"),
        swapMode,
        slippageBps,
        priceImpactPct: String(payload.priceImpactPct ?? "0"),
        routeLabels,
        contextSlot: typeof payload.contextSlot === "number" ? payload.contextSlot : null,
      },
    });
  } catch {
    return jsonError("PROVIDER_UNAVAILABLE", "The quote provider is unavailable.", 502, true);
  }
}
